mapper.sql:
WHERE o.deleted = 0

    AND o.user_id = #{userId}


    AND o.status = #{query.status}


    AND o.pay_status = #{query.payStatus}


    AND o.stall_id = #{query.stallId}


    AND (o.order_no LIKE CONCAT('%', #{query.keyword}, '%')
         OR s.name LIKE CONCAT('%', #{query.keyword}, '%')
         OR u.real_name LIKE CONCAT('%', #{query.keyword}, '%'))

mapper.select:
SELECT i.id, i.order_id AS orderId, i.dish_id AS dishId, i.dish_name AS dishName, d.image AS dishImage, i.price, i.quantity, i.price * i.quantity AS amount FROM dining_order_item i LEFT JOIN dish d ON d.id = i.dish_id AND d.deleted = 0 WHERE i.deleted = 0 AND i.order_id IN
#{id}
ORDER BY i.id
